function drawSalonPattern(c,p){const x=c.getContext('2d'),col=p.v%5,row=p.cat,cw=atlas.width/5,ch=atlas.height/8; x.clearRect(0,0,180,300);x.save();const hue=[0,22,-22,65,155][Math.floor(p.v/5)];x.filter=`hue-rotate(${hue}deg)`;x.drawImage(atlas,col*cw+cw*.265,row*ch+ch*.025,cw*.49,ch*.90,0,0,180,300);x.restore();if(p.cat===1&&col===0)botanicalNude(x,Math.floor(p.v/5));}
