function star(x,a,b,r,col){x.fillStyle=col;x.beginPath();for(let i=0;i<10;i++){let ang=i*Math.PI/5-Math.PI/2,rr=i%2?r*.42:r;x.lineTo(a+Math.cos(ang)*rr,b+Math.sin(ang)*rr)}x.closePath();x.fill()}
