function syncDesignColourPanel(){if($('#animalColours').hidden)return;const id=blocks[active].patternId;if(!Number.isInteger(id)||!patterns[id]){$('#animalColours').hidden=true;colourSlot=-1;return}if(colourPatternId!==id)colourSlot=-1;colourPatternId=id;updateDesignColourControls()}
function restoreOriginalDesign(all=false){const id=Number.isInteger(blocks[active].patternId)?blocks[active].patternId:colourPatternId;const p=patterns[id];if(!p)return;const affected=new Set(all?patterns.map(p=>p.id):[id]);if(all){designPalettes.clear();patterns.forEach(pattern=>pattern.exactSelections?.clear())}else{designPalettes.delete(id);p.exactSelections?.clear()}blocks.forEach((b,i)=>{if(affected.has(b.patternId)||(!all&&i===active)){const original=patterns[b.patternId]||p;b.history.push(b.canvas.getContext('2d').getImageData(0,0,180,300));if(b.history.length>15)b.history.shift();drawOriginalPattern(b.canvas,original);b.patternId=original.id;b.name=original.name}});colourPatternId=id;colourSlot=-1;loadActive();renderLibrary();updateDesignColourControls();toast(all?'All original pattern colours restored':'Original design colours restored')}
function rgbFeature(r,g,b){let vals=[r,g,b].map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4});const x=(vals[0]*.4124+vals[1]*.3576+vals[2]*.1805)/.95047,y=vals[0]*.2126+vals[1]*.7152+vals[2]*.0722,z=(vals[0]*.0193+vals[1]*.1192+vals[2]*.9505)/1.08883;const f=v=>v>.008856?Math.cbrt(v):7.787*v+16/116,fx=f(x),fy=f(y),fz=f(z);return [(116*fy-16)*.65,500*(fx-fy),200*(fy-fz)]}
// Preserve realistic lighting while grouping shades of the same base colour.
function colourGroupDistance(a,b){return (a[0]-b[0])**2*.10+(a[1]-b[1])**2+(a[2]-b[2])**2}
function detectDesignColours(data,width,height,foreground=null){
 const pixels=width*height,features=new Float32Array(pixels*3),samples=[];const dist=(a,b)=>(a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2;
 for(let p=0;p<pixels;p++){const i=p*4,f=rgbFeature(data[i],data[i+1],data[i+2]);features.set(f,p*3);const x=p%width,y=Math.floor(p/width);if((!foreground||foreground[p])&&data[i+3]>15&&p%9===0&&x>width*.15&&x<width*.85&&y>height*.08&&y<height*.96)samples.push({f,rgb:[data[i],data[i+1],data[i+2]]})}
 if(!samples.length)return {colours:['#e9bbb3'],labels:new Uint8Array(pixels),shades:new Float32Array(pixels).fill(1)};
 let centres=[samples[Math.floor(samples.length/2)].f.slice()];while(centres.length<8){let best=-1,far=samples[0].f;for(const p of samples){const d=Math.min(...centres.map(c=>dist(p.f,c)));if(d>best){best=d;far=p.f}}if(best<36)break;centres.push(far.slice())}
 for(let iteration=0;iteration<6;iteration++){const sums=centres.map(()=>[0,0,0,0]);for(const p of samples){let k=0;for(let n=1;n<centres.length;n++)if(dist(p.f,centres[n])<dist(p.f,centres[k]))k=n;for(let j=0;j<3;j++)sums[k][j]+=p.f[j];sums[k][3]++}centres=centres.map((c,k)=>sums[k][3]?sums[k].slice(0,3).map(v=>v/sums[k][3]):c)}
 let groups=centres.map(f=>({f:f.slice(),n:0,rgb:[0,0,0]}));for(const p of samples){let k=0;for(let n=1;n<centres.length;n++)if(dist(p.f,centres[n])<dist(p.f,centres[k]))k=n;groups[k].n++;for(let j=0;j<3;j++)groups[k].rgb[j]+=p.rgb[j]}
 groups=groups.filter(g=>g.n>0).map(g=>({...g,rgb:g.rgb.map(v=>v/g.n)}));
 for(;;){let pair=null,best=Infinity;for(let i=0;i<groups.length;i++)for(let j=i+1;j<groups.length;j++){const d=dist(groups[i].f,groups[j].f),tiny=Math.min(groups[i].n,groups[j].n)<samples.length*.018;const chroma=Math.hypot(groups[i].f[1]-groups[j].f[1],groups[i].f[2]-groups[j].f[2]),light=Math.abs(groups[i].f[0]-groups[j].f[0]);if((d<81||(chroma<11&&light<43)||(tiny&&chroma<17&&light<48))&&d<best){best=d;pair=[i,j]}}if(!pair)break;const [a,b]=pair,n=groups[a].n+groups[b].n;groups[a]={n,f:groups[a].f.map((v,j)=>(v*groups[a].n+groups[b].f[j]*groups[b].n)/n),rgb:groups[a].rgb.map((v,j)=>(v*groups[a].n+groups[b].rgb[j]*groups[b].n)/n)};groups.splice(b,1)}
 groups.sort((a,b)=>b.n-a.n);const labels=new Uint8Array(pixels).fill(255),shades=new Float32Array(pixels);for(let p=0;p<pixels;p++){if((foreground&&!foreground[p])||data[p*4+3]<16)continue;const f=[features[p*3],features[p*3+1],features[p*3+2]];let k=0;for(let j=1;j<groups.length;j++)if(colourGroupDistance(f,groups[j].f)<colourGroupDistance(f,groups[k].f))k=j;labels[p]=k;const i=p*4,lum=data[i]*.2126+data[i+1]*.7152+data[i+2]*.0722,rgb=groups[k].rgb,base=rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;shades[p]=Math.max(.72,Math.min(1.22,(lum+24)/(base+24)))}
 const colours=groups.map(g=>'#'+g.rgb.map(v=>Math.round(v).toString(16).padStart(2,'0')).join(''));return {colours,labels,shades}
}

function nativeLab(r,g,b){const f=rgbFeature(r,g,b);return [f[0]/.65,f[1],f[2]]}
function hexLab(hex){const c=hex.match(/\w\w/g).map(v=>parseInt(v,16));return nativeLab(...c)}
function labRgb(L,a,b){let y=(L+16)/116,x=y+a/500,z=y-b/200;const inv=v=>v**3>.008856?v**3:(v-16/116)/7.787;x=.95047*inv(x);y=inv(y);z=1.08883*inv(z);const rgb=[x*3.2406-y*1.5372-z*.4986,-x*.9689+y*1.8758+z*.0415,x*.0557-y*.204+z*1.057];return rgb.map(v=>Math.round(Math.max(0,Math.min(255,(v<=.0031308?v*12.92:1.055*Math.max(0,v)**(1/2.4)-.055)*255))))}
function gamutSafeLabRgb(L,a,b){const raw=(a,b)=>{let y=(L+16)/116,x=y+a/500,z=y-b/200;const inv=v=>v**3>.008856?v**3:(v-16/116)/7.787;x=.95047*inv(x);y=inv(y);z=1.08883*inv(z);return [x*3.2406-y*1.5372-z*.4986,-x*.9689+y*1.8758+z*.0415,x*.0557-y*.204+z*1.057]};const valid=rgb=>rgb.every(v=>v>=-.00001&&v<=1.00001);if(valid(raw(a,b)))return labRgb(L,a,b);let lo=0,hi=1;for(let n=0;n<14;n++){const mid=(lo+hi)/2;if(valid(raw(a*mid,b*mid)))lo=mid;else hi=mid}return labRgb(L,a*lo,b*lo)}
function transferOriginalPixel(rgb,sourceLab,targetLab,opacity=1){if(opacity<=0)return rgb.slice();if(Math.hypot(...targetLab.map((v,i)=>v-sourceLab[i]))<.00001)return rgb.slice();const lab=nativeLab(...rgb),L=Math.max(0,Math.min(100,lab[0]+targetLab[0]-sourceLab[0]));const result=gamutSafeLabRgb(L,targetLab[1],targetLab[2]);return rgb.map((v,i)=>Math.round(v*(1-opacity)+result[i]*opacity))}

function preciseColourMask(data,width,height,seed,tolerance=10,connected=true){const n=width*height,offset=seed*4,source=nativeLab(data[offset],data[offset+1],data[offset+2]),weights=new Float32Array(n);for(let p=0;p<n;p++){const i=p*4;if(data[i+3]<16)continue;const lab=nativeLab(data[i],data[i+1],data[i+2]),distance=Math.hypot(lab[0]-source[0],lab[1]-source[1],lab[2]-source[2]);const w=Math.max(0,Math.min(1,(tolerance-distance)/Math.min(3,tolerance/2)));weights[p]=w*w*(3-2*w)}if(!connected)return weights;const result=new Float32Array(n),seen=new Uint8Array(n),stack=[seed];while(stack.length){const p=stack.pop();if(seen[p])continue;seen[p]=1;if(weights[p]<=0)continue;result[p]=weights[p];const x=p%width,y=Math.floor(p/width);if(x>0)stack.push(p-1);if(x<width-1)stack.push(p+1);if(y>0)stack.push(p-width);if(y<height-1)stack.push(p+width)}return result}
function recolourDesign(c,p,colours){const x=c.getContext('2d',{willReadFrequently:true}),img=x.getImageData(0,0,180,300),regions=analysePattern(p);const prototypes=regions.colours.map(hexLab),targets=colours.map(hex=>hex?hexLab(hex):null),exactEdits=targets.map((target,slot)=>({target,slot,selection:p.exactSelections?.get(slot)})).filter(e=>e.target&&e.selection);for(let pixel=0;pixel<regions.labels.length;pixel++){if(regions.foreground&&!regions.foreground[pixel])continue;const i=pixel*4,original=[img.data[i],img.data[i+1],img.data[i+2]],lab=nativeLab(...original);let result=original;const automaticSlot=regions.labels[pixel];let exactWinner=-1,exactOrder=-1;for(const entry of exactEdits)if(entry.selection.weights[pixel]>0&&(entry.selection.order||0)>=exactOrder){exactWinner=entry.slot;exactOrder=entry.selection.order||0}for(let slot=0;slot<targets.length;slot++){if(!targets[slot]||(exactWinner>=0&&slot!==exactWinner))continue;const exact=p.exactSelections?.get(slot);let weight=exact?exact.weights[pixel]:(automaticSlot===slot?1:0);if(weight<=0)continue;const source=exact?.lab||prototypes[slot];if(lab[0]>92&&Math.hypot(lab[1],lab[2])<8)weight*=Math.max(0,(100-lab[0])/8);result=transferOriginalPixel(original,source,targets[slot],weight)}for(let j=0;j<3;j++)img.data[i+j]=result[j]}x.putImageData(img,0,0)}
function pickExactArea(a,b){const p=patterns[colourPatternId];if(!p)return;const info=analysePattern(p),seed=b*180+a;if(info.foreground&&!info.foreground[seed]){toast('That area is outside the nail. Click inside the design.');return}let data=info.originalData;if(!data){const source=document.createElement('canvas');source.width=180;source.height=300;drawOriginalPattern(source,p);data=source.getContext('2d').getImageData(0,0,180,300).data}const i=seed*4,hex='#'+[data[i],data[i+1],data[i+2]].map(v=>v.toString(16).padStart(2,'0')).join(''),selection={seed,hex,order:Date.now(),lab:nativeLab(data[i],data[i+1],data[i+2]),weights:preciseColourMask(data,180,300,seed,+$('#preciseRange').value,$('#preciseScope').value==='area')};if(info.foreground)for(let k=0;k<selection.weights.length;k++)if(!info.foreground[k])selection.weights[k]=0;if(colourSlot<0)colourSlot=info.labels[seed];if(!p.exactSelections)p.exactSelections=new Map();p.exactSelections.set(colourSlot,selection);pickingExact=false;$('#pickExactPart').classList.remove('active');if(designPalettes.get(p.id)?.[colourSlot]){snapshot();drawPattern(blocks[active].canvas,p)}loadActive();showSelectedArea();toast('Exact original area selected. Now pick its new colour.')}
function showSelectedArea(){const p=patterns[colourPatternId],selected=p?.exactSelections?.get(colourSlot);if(!selected){toast('Use Pick exact part, then click the original nail.');return}ctx.clearRect(0,0,180,300);ctx.drawImage(blocks[active].canvas,0,0);const img=ctx.getImageData(0,0,180,300);for(let k=0;k<selected.weights.length;k++){const t=selected.weights[k]*.45;if(!t)continue;img.data[k*4]=Math.round(img.data[k*4]*(1-t)+15*t);img.data[k*4+1]=Math.round(img.data[k*4+1]*(1-t)+210*t);img.data[k*4+2]=Math.round(img.data[k*4+2]*(1-t)+245*t)}ctx.putImageData(img,0,0);previewSelection=true;$('#animalColourStatus').textContent='Blue preview shows the exact area selected. Pick a colour to apply it.'}
$('#pickExactPart').onclick=()=>{if(colourSlot<0)return;pickingExact=!pickingExact;$('#pickExactPart').classList.toggle('active',pickingExact);if(pickingExact){drawOriginalPattern(editor,patterns[colourPatternId]);$('#animalColourStatus').textContent='Click the exact part on the ORIGINAL nail above.'}else loadActive()};
$('#showExactArea').onclick=()=>{if(previewSelection)loadActive();else showSelectedArea()};
function refineExactSelection(){const p=patterns[colourPatternId],selection=p?.exactSelections?.get(colourSlot);if(selection)pickExactArea(selection.seed%180,Math.floor(selection.seed/180))}
$('#preciseRange').onchange=refineExactSelection;$('#preciseScope').onchange=refineExactSelection;
$('#compareOriginal').onclick=()=>{const p=patterns[colourPatternId];if(!p)return;if(comparingOriginal){loadActive()}else{drawOriginalPattern(editor,p);comparingOriginal=true;previewSelection=false;$('#compareOriginal').textContent='Show edited design'}};

function registerActiveDesign(name=blocks[active].name){const source=document.createElement('canvas');source.width=180;source.height=300;source.getContext('2d').drawImage(blocks[active].canvas,0,0);const p={id:patterns.length,cat:8,v:0,name:name||'My design',sourceCanvas:source};patterns.push(p);blocks[active].patternId=p.id;colourPatternId=p.id;colourSlot=-1;$('#animalColours').hidden=false;loadActive();return p}
$('#detectActiveColours').onclick=()=>{registerActiveDesign();toast('Main colours detected. Choose a colour button to edit.')};


// V15: separate numbered colour blocks; the first is the largest detected colour region.
function renderQuickColourBlocks(){
 const wrap=$('#quickColourBlocks'),palette=$('#quickColourPalette'),message=$('#quickColourMessage');if(!wrap)return;
 wrap.replaceChildren();const id=blocks[active].patternId,p=patterns[id];
 if(!Number.isInteger(id)||!p){palette.hidden=true;message.textContent='Select a design from the pattern library to show its numbered colours.';return}
 const info=analysePattern(p),custom=designPalettes.get(id)||[];
 message.textContent='Choose Block 1 for the main colour, or another numbered block for its design detail.';
 info.colours.forEach((original,i)=>{
  const c=custom[i]||p.exactSelections?.get(i)?.hex||original;
  const b=document.createElement('button');b.className='quick-colour-block';b.classList.toggle('active',colourPatternId===id&&colourSlot===i);
  b.setAttribute('aria-label','Block '+(i+1)+(i===0?' main colour':' design colour')+' '+c);
  const number=document.createElement('span');number.className='number';number.textContent=i+1;
  const chip=document.createElement('span');chip.className='colour-dot';chip.style.background=c;
  const label=document.createElement('span');label.textContent=i===0?'Main colour':'Colour '+(i+1);
  b.append(number,chip,label);b.onclick=()=>{colourPatternId=id;colourSlot=i;$('#animalColours').hidden=false;updateDesignColourControls();renderQuickColourBlocks()};wrap.append(b);
 });
 palette.hidden=colourPatternId!==id||colourSlot<0;
 if(!palette.hidden){const chosen=custom[colourSlot]||info.colours[colourSlot];$('#quickColourCustom').value=chosen;message.textContent='Block '+(colourSlot+1)+' selected. Click a replacement colour below.'}
}
function quickReplace(c){const id=blocks[active].patternId;if(!Number.isInteger(id))return;colourPatternId=id;if(colourSlot<0)colourSlot=0;chooseDesignColour(c);renderQuickColourBlocks()}
swatches.forEach(c=>{const b=document.createElement('button');b.style.background=c;b.title=c;b.setAttribute('aria-label','Replace selected nail block with '+c);b.onclick=()=>quickReplace(c);$('#quickColourSwatches').append(b)});
$('#quickColourCustom').onchange=e=>quickReplace(e.target.value);
